<?php use App\Core\Helpers as H; ?><header class="dashboard-heading"><h1>Social Publishing Integrations</h1></header><p>Disable a provider to stop all publishing attempts safely. Existing connections are retained.</p><div class="dashboard-grid"><?php foreach($integrations as $i):?><form class="card" method="post" action="/admin/social-publishing/<?=H::e($i['platform'])?>"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><h2><?=H::e(ucfirst($i['platform']))?></h2><label><input type="checkbox" name="enabled" value="1" <?=$i['is_enabled']?'checked':''?>> Publishing enabled</label><label>Disabled reason<textarea name="reason" maxlength="500"><?=H::e($i['disabled_reason'])?></textarea></label><button class="btn" type="submit">Save</button></form><?php endforeach;?></div>
